#include <stdio.h>
#include <math.h>



int main(void) {
    double a, b, c;
    scanf("%lf%lf%lf", &a, &b, &c);
    if (a <= 0 || b <= 0 || c <= 0 || a + b <= c || a + c <= b || b + c <= a) puts("INVALID");
    else {
        double p = (a + b + c) / 2;
        printf("%.2f\n", sqrt(p * (p - a) * (p - b) * (p - c)));
    }
    return 0;
}
